#!/usr/bin/env python3
"""Embedded exact HELIXNID Carrier Precision Model V1.

Compressed artifact generated from the verified Olist orders file with SHA256
8df58ef3d2d7e9944010f7beecd9b75367f5588ec6e3c91cec19ae3345ef9ecf and all
96,281 valid completed orders. This module exists only to make deployment startup
offline and deterministic; it does not change the locked holdout evidence.
"""
from __future__ import annotations

import base64
import gzip
import hashlib
import json
from pathlib import Path

MODEL_B64_GZIP = """
"""

EXPECTED_DATASET_SHA256 = "8df58ef3d2d7e9944010f7beecd9b75367f5588ec6e3c91cec19ae3345ef9ecf"
EXPECTED_TRAINED_ROWS = 96281


def model_bytes() -> bytes:
    raw = gzip.decompress(base64.b64decode(MODEL_B64_GZIP))
    artifact = json.loads(raw)
    if artifact.get("dataset_sha256") != EXPECTED_DATASET_SHA256:
        raise RuntimeError("embedded model dataset hash mismatch")
    if artifact.get("trained_real_completed_orders") != EXPECTED_TRAINED_ROWS:
        raise RuntimeError("embedded model training-row mismatch")
    return raw


def write_model(path: Path) -> dict:
    raw = model_bytes()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    artifact = json.loads(raw)
    artifact["embedded_artifact_sha256"] = hashlib.sha256(raw).hexdigest()
    return artifact
